def doubleBasePalindromeSum(limit):
    total = 0
    for length in range(1, len(str(limit)) + 1):
        half = (length + 1) // 2
        for pre in range(10 ** (half - 1), 10 ** half):
            s = str(pre)
            full = s + s[::-1] if length % 2 == 0 else s + s[-2::-1]
            x = int(full)
            if x > limit:
                continue
            b = bin(x)[2:]
            if b == b[::-1]:
                total += x
    return total
